(7, 'Apple iMac 24\" M3', 'ابل ايماك 24 بوصة M3', NULL, 'apple-imac-24-m3', 'APPLE-IMAC24-M3', '24\" 4.5K Retina, M3 chip, 8GB unified memory, 256GB SSD', 'شاشة 24 بوصة 4.5K Retina، شريحة M3، 8 جيجا ذاكرة موحدة، 256 جيجا SSD', NULL, 'The all-in-one iMac with stunning 24-inch 4.5K Retina display and powerful M3 chip. Available in vibrant colors, featuring advanced camera and studio-quality mics. Perfect for creative work and everyday tasks.', 'جهاز iMac الكل في واحد مع شاشة Retina مذهلة بحجم 24 بوصة بدقة 4.5K وشريحة M3 قوية. متوفر بألوان نابضة بالحياة، ويتميز بكاميرا متقدمة وميكروفونات بجودة الاستوديو. مثالي للعمل الإبداعي والمهام اليومية.', NULL, 7499.00, NULL, NULL, 10, 5, 'images/products/screen.png', 5, 7, 1, 1, 1, 0, 1, 'in_stock', NULL, NULL, NULL, NULL, NULL, 4915, 0, 0.0, 0, NULL, NULL, 'imac, apple, all-in-one, desktop, m3, creative, design, 4k, retina', NULL, NULL, '2025-10-22 18:01:24', '2025-10-28 11:13:49', NULL),
(8, 'Dell UltraSharp 32\" 4K Monitor', 'ديل الترا شارب 32 بوصة 4K', NULL, 'dell-ultrasharp-32-4k', 'DELL-US32-4K', '32\" 4K UHD IPS, 99% sRGB, USB-C, Height Adjustable', '32 بوصة 4K UHD IPS، 99% sRGB، USB-C، قابل لتعديل الارتفاع', NULL, 'Professional-grade Dell UltraSharp 32\" 4K monitor with stunning color accuracy (99% sRGB), USB-C connectivity, and ergonomic stand. Perfect for content creators and professionals.', 'شاشة Dell UltraSharp 32 بوصة 4K ذات الدرجة الاحترافية مع دقة ألوان مذهلة (99٪ sRGB) واتصال USB-C وحامل مريح. مثالي لمنشئي المحتوى والمحترفين.', NULL, 2999.00, NULL, NULL, 15, 5, 'images/products/screen.png', 19, 1, 1, 1, 1, 0, 1, 'in_stock', NULL, NULL, NULL, NULL, NULL, 1653, 0, 0.0, 0, NULL, NULL, 'monitor, dell, ultrasharp, 4k, professional, color accurate, usb-c, content creation', NULL, NULL, '2025-10-22 18:01:24', '2025-10-27 18:28:19', NULL),
(9, 'NVIDIA GeForce RTX 4090', 'انفيديا جي فورس RTX 4090', NULL, 'nvidia-rtx-4090', 'NVIDIA-RTX4090', '24GB GDDR6X, Ada Lovelace, Ray Tracing, DLSS 3', '24 جيجا GDDR6X، Ada Lovelace، تتبع الأشعة، DLSS 3', NULL, 'The ultimate graphics card for gaming and creation. NVIDIA RTX 4090 delivers revolutionary performance with 24GB memory, Ada Lovelace architecture, and DLSS 3. Play at 4K with maxed-out settings.', 'بطاقة الرسومات النهائية للألعاب والإبداع. يقدم NVIDIA RTX 4090 أداءً ثوريًا مع ذاكرة 24 جيجابايت وبنية Ada Lovelace و DLSS 3. العب بدقة 4K مع الإعدادات القصوى.', NULL, 8999.00, NULL, NULL, 3, 5, 'images/products/rtx2.png', 11, 11, 1, 1, 0, 0, 1, 'in_stock', NULL, NULL, NULL, NULL, NULL, 4785, 0, 0.0, 0, NULL, NULL, 'graphics card, gpu, nvidia, rtx 4090, gaming, high-end, 4k, ray tracing, powerful', NULL, NULL, '2025-10-22 18:01:24', '2025-10-22 18:30:37', NULL),
(10, 'Samsung 990 PRO 2TB NVMe SSD', 'سامسونج 990 PRO 2 تيرابايت NVMe SSD', NULL, 'samsung-990-pro-2tb', 'SAMS-990PRO-2TB', '2TB, PCIe 4.0, 7,450 MB/s Read, 6,900 MB/s Write', '2 تيرابايت، PCIe 4.0، قراءة 7,450 ميجابايت/ثانية، كتابة 6,900 ميجابايت/ثانية', NULL, 'Lightning-fast storage with Samsung 990 PRO. Features blazing speeds up to 7,450 MB/s read and 6,900 MB/s write. PCIe 4.0 x4 interface with heatsink for optimal performance. Perfect for gaming and content creation.', 'تخزين سريع البرق مع Samsung 990 PRO. يتميز بسرعات مذهلة تصل إلى 7,450 ميجابايت/ثانية للقراءة و 6,900 ميجابايت/ثانية للكتابة. واجهة PCIe 4.0 x4 مع مبدد حراري للأداء الأمثل. مثالي للألعاب وإنشاء المحتوى.', NULL, 899.00, 799.00, NULL, 25, 5, 'images/products/ssd.png', 14, 8, 1, 1, 1, 0, 1, 'in_stock', NULL, NULL, NULL, NULL, NULL, 3546, 0, 0.0, 0, NULL, NULL, 'ssd, nvme, samsung, storage, fast, pcie 4.0, gaming, 2tb, solid state', NULL, NULL, '2025-10-22 18:01:24', '2025-10-22 18:30:37', NULL),
(11, 'AMD Ryzen 9 7950X', 'AMD رايزن 9 7950X', NULL, 'amd-ryzen-9-7950x', 'AMD-R9-7950X', '16 Cores, 32 Threads, 5.7GHz Max Boost, AM5 Socket', '16 نواة، 32 خيط، 5.7 جيجاهرتز بوست، مقبس AM5', NULL, 'Extreme performance with AMD Ryzen 9 7950X. 16 cores and 32 threads of processing power, up to 5.7GHz boost clock, and AMD 3D V-Cache technology. The ultimate CPU for gaming and content creation.', 'أداء متطرف مع AMD Ryzen 9 7950X. 16 نواة و 32 خيطًا من قوة المعالجة، وساعة تعزيز تصل إلى 5.7 جيجاهرتز، وتقنية AMD 3D V-Cache. وحدة المعالجة المركزية النهائية للألعاب وإنشاء المحتوى.', NULL, 2999.00, 2799.00, NULL, 12, 5, 'images/products/mouse.png', 10, 10, 1, 1, 0, 0, 1, 'in_stock', NULL, NULL, NULL, NULL, NULL, 1682, 0, 0.0, 0, NULL, NULL, 'processor, cpu, amd, ryzen 9, high-end, gaming, productivity, 16 core', NULL, NULL, '2025-10-22 18:01:24', '2025-10-22 18:30:37', NULL),
(12, 'Intel Core i9-13900K', 'انتل كور i9-13900K', NULL, 'intel-i9-13900k', 'INTEL-I9-13900K', '24 Cores, 32 Threads, 5.8GHz Max Turbo, LGA1700', '24 نواة، 32 خيط، 5.8 جيجاهرتز توربو، LGA1700', NULL, 'Unleash extreme performance with Intel Core i9-13900K. 24 cores (8P+16E), 32 threads, and up to 5.8GHz turbo frequency. Raptor Lake architecture delivers exceptional gaming and multitasking performance.', 'أطلق العنان للأداء المتطرف مع Intel Core i9-13900K. 24 نواة (8P+16E)، و 32 خيطًا، وتردد توربو يصل إلى 5.8 جيجاهرتز. توفر بنية Raptor Lake أداءً استثنائيًا للألعاب والمهام المتعددة.', NULL, 2799.00, 2599.00, NULL, 15, 5, 'images/products/rtx3.png', 10, 9, 1, 1, 1, 0, 1, 'in_stock', NULL, NULL, NULL, NULL, NULL, 2619, 0, 0.0, 0, NULL, NULL, 'processor, cpu, intel, i9, gaming, high-end, raptor lake, performance', NULL, NULL, '2025-10-22 18:01:24', '2025-10-22 18:30:37', NULL),
(13, 'ASUS TUF Gaming GeForce RTX ™ 5070 Ti', 'ASUS TUF Gaming GeForce RTX ™ 5070 Ti', 'ASUS TUF Gaming GeForce RTX ™ 5070 Ti', 'asus-tuf-gaming-geforce-rtx-5070-ti', 'SKU-OO9SWWAWVW', 'Powerful ASUS TUF Gaming GeForce RTX™ 5070 Ti delivers exceptional performance for gaming and creative work with advanced cooling and durability.', 'كرت شاشة ASUS TUF Gaming GeForce RTX™ 5070 Ti يقدم أداءً فائقًا للألعاب والتصميم مع تبريد متطور وجودة تصنيع عالية.', 'כרטיס המסך ASUS TUF Gaming GeForce RTX™ 5070 Ti מספק ביצועים עוצמתיים לגיימינג ולעיצוב גרפי, עם מערכת קירור מתקדמת ואמינות גבוהה.', 'The ASUS TUF Gaming GeForce RTX™ 5070 Ti redefines high-performance gaming with NVIDIA’s cutting-edge Ada Lovelace architecture. Equipped with advanced cooling technology, military-grade components, and a reinforced metal shroud, it ensures durability and stable performance even under heavy load.\r\nEnjoy ultra-smooth gameplay, real-time ray tracing, and AI-powered graphics for the most immersive gaming experience. Ideal for gamers, creators, and professionals who demand reliability and performance.\r\n\r\nKey Features:\r\n\r\nNVIDIA GeForce RTX™ 5070 Ti GPU\r\n\r\n8GB GDDR6X memory\r\n\r\nDual ball fan bearings for longer lifespan\r\n\r\nMilitary-grade capacitors for enhanced durability\r\n\r\nMetal backplate for extra rigidity\r\n\r\nSupport for real-time ray tracing and DLSS 3', 'كرت الشاشة ASUS TUF Gaming GeForce RTX™ 5070 Ti يمنحك تجربة ألعاب احترافية بفضل معمارية NVIDIA الحديثة Ada Lovelace.\r\nيتميز بتصميم متين وجودة تصنيع عالية مع نظام تبريد متطور يضمن أداءً ثابتًا ودرجات حرارة منخفضة حتى أثناء اللعب المكثف.\r\nيقدم أداءً مذهلاً في تتبع الأشعة (Ray Tracing) وتقنيات الذكاء الاصطناعي (DLSS 3)، مما يوفر تجربة بصرية غامرة وسلسة.\r\nمثالي للاعبين، المصممين، وصناع المحتوى الذين يبحثون عن القوة والثبات في الأداء.\r\n\r\nالمميزات الأساسية:\r\n\r\nمعالج رسومي NVIDIA GeForce RTX™ 5070 Ti\r\n\r\nذاكرة GDDR6X بسعة 8 جيجابايت\r\n\r\nمراوح بتقنية الكرات المزدوجة لزيادة العمر الافتراضي\r\n\r\nمكثفات بمعايير عسكرية لتعزيز المتانة\r\n\r\nغطاء معدني خلفي لمزيد من الصلابة\r\n\r\nدعم تقنيات Ray Tracing و DLSS 3', 'כרטיס המסך ASUS TUF Gaming GeForce RTX™ 5070 Ti מביא רמת ביצועים חדשה לגיימרים וליוצרים מקצועיים, עם ארכיטקטורת Ada Lovelace החדשנית של NVIDIA.\r\nהכרטיס כולל מערכת קירור משופרת, רכיבים באיכות צבאית ושלדה מתכתית חזקה, המבטיחים פעולה יציבה ועמידות לאורך זמן.\r\nהוא תומך בטכנולוגיות מתקדמות כמו Ray Tracing בזמן אמת ו-DLSS 3 המופעלת בבינה מלאכותית, המעניקות חוויית משחק חלקה ואיכותית במיוחד.\r\nמתאים לגיימרים, מעצבים ויוצרי תוכן המחפשים ביצועים אמינים ועוצמתיים.\r\n\r\nמאפיינים עיקריים:\r\n\r\nמעבד גרפי NVIDIA GeForce RTX™ 5070 Ti\r\n\r\nזיכרון GDDR6X בנפח 8GB\r\n\r\nמאווררים עם מיסבים כפולים לאריכות ימים\r\n\r\nקבלים באיכות צבאית לעמידות מוגברת\r\n\r\nגב מתכתי לחוזק נוסף\r\n\r\nתמיכה ב-Ray Tracing ו-DLSS 3', 1000.00, 850.00, NULL, 99, 5, 'https://m.media-amazon.com/images/I/81POeoI3lSL._AC_SL1500_.jpg', 115, 4, 1, 1, 1, 1, 1, 'in_stock', NULL, NULL, NULL, NULL, NULL, 0, 0, 0.0, 0, NULL, NULL, NULL, 'كرت شاشة, كروت شاشة, بطاقة رسومية, بطاقة جرافيك, RTX 5070 Ti, RTX5070Ti, اسوس, ASUS, TUF Gaming, GeForce, RTX, بطاقة عرض, كرت ألعاب, كرت جيمينغ, كرت جرافيك قوي, كرت شاشة لتجميع كمبيوتر, كرت شاشة احترافي, كرت شاشة لتصميم الجرافيك, graphic card, graphics cards, GPU, gaming GPU, Palestine', NULL, '2025-10-23 19:08:51', '2025-10-25 09:32:27', '2025-10-25 09:32:27'),
